package ocean.service;
import ocean.database.DatabaseConnection; import ocean.model.Message; import ocean.utils.ValidationUtil; import java.sql.*; import java.time.LocalDateTime; import java.util.*;
public class MessageService implements Service {
 public void initialize() throws SQLException {DatabaseConnection.initialize();}
 public Message release(String text,String category) throws SQLException {Message m=new Message(ValidationUtil.validate(text),category);try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO messages VALUES(?,?,?,?,0)")){p.setString(1,m.getId());p.setString(2,m.getText());p.setString(3,m.getCategory());p.setString(4,m.getCreatedAt().toString());p.executeUpdate();}return m;}
 public List<Message> randomBatch(Set<String> excluded,int limit) throws SQLException {List<Message> out=new ArrayList<>();String sql="SELECT * FROM messages"+(excluded.isEmpty()?"":" WHERE message_id NOT IN ("+String.join(",",Collections.nCopies(excluded.size(),"?"))+")")+" ORDER BY RANDOM() LIMIT ?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){int i=1;for(String id:excluded)p.setString(i++,id);p.setInt(i,limit);try(ResultSet r=p.executeQuery()){while(r.next())out.add(read(r));}}return out;}
 public Optional<Message> random(Set<String> excluded) throws SQLException {List<Message> rows=randomBatch(excluded,1);if(rows.isEmpty()&&!excluded.isEmpty())rows=randomBatch(Set.of(),1);if(rows.isEmpty())return Optional.empty();Message m=rows.get(0);try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE messages SET discovery_count=discovery_count+1 WHERE message_id=?")){p.setString(1,m.getId());p.executeUpdate();}return Optional.of(m);}
 private Message read(ResultSet r)throws SQLException{return new Message(r.getString("message_id"),r.getString("message_text"),r.getString("category"),LocalDateTime.parse(r.getString("created_at")),r.getInt("discovery_count"));}
 public int count() throws SQLException {try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM messages")){return r.next()?r.getInt(1):0;}}
 public int totalDiscoveries() throws SQLException {try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COALESCE(SUM(discovery_count),0) FROM messages")){return r.next()?r.getInt(1):0;}}
 public Map<String,Integer> categories() throws SQLException {Map<String,Integer> m=new LinkedHashMap<>();try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT category,COUNT(*) n FROM messages GROUP BY category")){while(r.next())m.put(r.getString(1),r.getInt(2));}return m;}
}
